Complete local C example; the app itself does not execute it:
```c
#include <stdio.h>
#include <stdlib.h>

struct Node { int value; struct Node *next; };
void clear(struct Node *head) {
 while (head != NULL) {
  struct Node *next = head->next;
  free(head);
  head = next;
 }
}
int main(void) {
 struct Node *a = malloc(sizeof *a);
 if (a == NULL) { return 1; }
 struct Node *b = malloc(sizeof *b);
 if (b == NULL) { free(a); return 1; }
 *b = (struct Node){.value = 8, .next = NULL};
 *a = (struct Node){.value = 3, .next = b};
 printf("%d\n", a->next->value);
 clear(a);
}
```

